<?php $accountLabels=['pending'=>__('Chờ duyệt'),'approved'=>__('Đã duyệt'),'rejected'=>__('Bị từ chối')]; ?>
<section class="page-section"><div class="container-fluid"><div class="row"><div class="col-12"><div class="section-title"><div><p class="eyebrow"><?= e(__('TÀI CHÍNH')) ?></p><h1><?= e(__('Hoàn tiền Guest')) ?></h1><p><?= e(__('Tạo lệnh theo chính sách, chuyển bằng VietQR rồi nhập mã giao dịch để đóng lệnh.')) ?></p></div></div>
<section class="surface-card"><div class="section-title compact"><div><h2><?= e(__('Tài khoản nhận tiền của Guest')) ?></h2><p><?= e(__('Đối chiếu chủ tài khoản trước khi duyệt.')) ?></p></div></div><form class="form-row align-items-end" method="get"><div class="form-group col-md-5"><label for="refund-account-status"><?= e(__('Trạng thái')) ?></label><select class="form-control" id="refund-account-status" name="status"><option value=""><?= e(__('Tất cả')) ?></option><?php foreach($accountLabels as $value=>$label): ?><option value="<?= e($value) ?>" <?= $status===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-3"><button class="btn btn-outline-primary btn-block"><?= e(__('Lọc')) ?></button></div></form>
<?php if(!$accounts): ?><p class="text-muted mb-0"><?= e(__('Chưa có tài khoản cần xử lý.')) ?></p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Guest</th><th><?= e(__('Ngân hàng')) ?></th><th><?= e(__('Chủ tài khoản')) ?></th><th><?= e(__('Trạng thái')) ?></th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><strong><?= e($a['guest_name']) ?></strong><br><small><?= e($a['guest_email']) ?></small></td><td><?= e($a['bank_name']) ?> (<?= e($a['bank_id']) ?>)<br><small><?= e($a['account_no_masked']) ?></small></td><td><?= e($a['account_name']) ?></td><td><span class="status status-<?= e($a['status']) ?>"><?= e($accountLabels[$a['status']]??$a['status']) ?></span><?php if($a['status']==='pending'): ?><form class="mt-2" method="post" action="<?= e(url('/admin/guest-refund-accounts/'.(int)$a['id'].'/decide')) ?>"><?= csrf_field() ?><input class="form-control form-control-sm mb-1" name="reason" maxlength="500" placeholder="<?= e(__('Lý do nếu từ chối')) ?>"><div class="action-row"><button class="btn btn-sm btn-primary" name="decision" value="approved" data-confirm="<?= e(__('Duyệt tài khoản này?')) ?>"><?= e(__('Duyệt')) ?></button><button class="btn btn-sm btn-outline-danger" name="decision" value="rejected"><?= e(__('Từ chối')) ?></button></div></form><?php elseif($a['rejection_reason']): ?><br><small><?= e($a['rejection_reason']) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="mt-4"><div class="section-title compact"><div><h2><?= e(__('Lệnh hoàn tiền')) ?></h2><p><?= e(__('Thanh toán tại chỗ do Host thu không xuất hiện ở đây.')) ?></p></div></div><?php if(!$refunds): ?><div class="surface-card"><p class="text-muted mb-0"><?= e(__('Chưa có booking cần hoàn.')) ?></p></div><?php else: ?><?php foreach($refunds as $r): ?><article class="surface-card mb-3"><div class="section-title compact"><div><h3 class="h5 mb-1">Booking #<?= (int)$r['booking_id'] ?> · <?= e($r['title']) ?></h3><p class="small mb-0"><?= e($r['guest_name']) ?> · <?= e($r['guest_email']) ?></p></div><span class="status status-<?= e($r['row_type']==='eligible'?'pending':$r['refund_status']) ?>"><?= e($r['row_type']==='eligible'?__('Cần tạo lệnh'):($r['refund_status']==='paid'?__('Đã hoàn'):__('Chờ chuyển'))) ?></span></div><dl class="trust-facts"><dt><?= e(__('Số tiền hoàn')) ?></dt><dd><strong><?= e(number_format((float)$r['amount'],0,',','.').'đ') ?></strong></dd><dt><?= e(__('Nguồn thanh toán')) ?></dt><dd><?= e(__(\App\Models\Payment::methodLabel($r['payment_method']))) ?></dd><dt><?= e(__('Tài khoản')) ?></dt><dd><?= $r['account_status']==='missing'?e(__('Guest chưa cung cấp')):e($r['bank_name'].' · '.$r['account_no'].' · '.$r['account_name']) ?></dd></dl>
<?php if($r['row_type']==='eligible'): ?><?php if($r['account_status']==='approved'): ?><form method="post" action="<?= e(url('/admin/guest-refunds/bookings/'.(int)$r['booking_id'])) ?>"><?= csrf_field() ?><input type="hidden" name="shown_amount" value="<?= e($r['amount']) ?>"><div class="form-group"><label><?= e(__('Lý do hoàn tiền')) ?></label><input class="form-control" name="note" maxlength="500" required></div><button class="btn btn-primary" data-confirm="<?= e(__('Tạo lệnh hoàn {amount}đ?',['amount'=>number_format((float)$r['amount'],0,',','.')])) ?>"><?= e(__('Tạo lệnh hoàn')) ?></button></form><?php else: ?><div class="alert alert-warning mb-0"><?= e($r['account_status']==='missing'?__('Guest chưa cung cấp tài khoản nhận hoàn.'):__('Tài khoản nhận hoàn chưa được duyệt.')) ?></div><?php endif; ?>
<?php elseif($r['refund_status']==='pending'): ?><div class="payment-qr"><div><?php if($r['qr_url']): ?><img src="<?= e($r['qr_url']) ?>" alt="<?= e(__('VietQR hoàn tiền')) ?>"><?php else: ?><div class="alert alert-danger"><?= e(__('Không thể tạo VietQR từ thông tin đã duyệt.')) ?></div><?php endif; ?></div><div><p><strong><?= e(__('Nội dung:')) ?></strong> <code><?= e($r['reference']) ?></code></p><p><?= e($r['bank_name'].' · '.$r['account_no']) ?><br><?= e($r['account_name']) ?></p><form method="post" action="<?= e(url('/admin/guest-refunds/'.(int)$r['refund_id'].'/paid')) ?>"><?= csrf_field() ?><div class="form-group"><label><?= e(__('Mã giao dịch ngân hàng')) ?></label><input class="form-control" name="transaction_no" maxlength="100" required></div><div class="form-group"><label><?= e(__('Ghi chú')) ?></label><input class="form-control" name="note" maxlength="500"></div><button class="btn btn-primary" data-confirm="<?= e(__('Chỉ xác nhận sau khi ngân hàng báo chuyển thành công.')) ?>"><?= e(__('Xác nhận đã hoàn')) ?></button></form></div></div><?php else: ?><p class="mb-0"><strong><?= e(__('Mã giao dịch:')) ?></strong> <?= e($r['bank_transaction_no']) ?> · <?= e(display_date($r['paid_at'],true)) ?></p><?php endif; ?></article><?php endforeach; ?><?php endif; ?></section></div></div></div></section>
